import React, { useState, useEffect } from 'react';
import { Message, QuestionResponse, HistoryDataPoint } from './types';
import { askQuestion, getCategories, getUserProgress, clearUserHistory, CategoryInfo } from './api';
import { Sidebar } from './components/Sidebar';
import { ChatContainer } from './components/ChatContainer';
import { TrendChart } from './components/TrendChart';
import { ReportPanel } from './components/ReportPanel';
import { UserSelector } from './components/UserSelector';
import './App.css';

const DEMO_QUESTIONS = [
  '最近学习压力很大，学不进去怎么办？',
  '我感觉很孤独，没有朋友',
  '和室友关系不好，很烦恼',
  '担心未来找不到工作',
  '总是情绪低落，提不起劲'
];

const createWelcomeMessage = (): Message => ({
  id: '1',
  type: 'bot',
  content: '您好！欢迎来到心理港湾。请问您有什么困扰或问题想要倾诉吗？',
  timestamp: new Date().toLocaleString('zh-CN')
});

const emotionToMetrics = (emotion: QuestionResponse['emotion']['emotion']) => {
  const profile: Record<typeof emotion, { stress: number; anxiety: number; stability: number }> = {
    happy: { stress: 28, anxiety: 25, stability: 86 },
    sad: { stress: 65, anxiety: 58, stability: 45 },
    anxious: { stress: 78, anxiety: 80, stability: 38 },
    angry: { stress: 72, anxiety: 56, stability: 42 },
    lonely: { stress: 60, anxiety: 53, stability: 48 },
    neutral: { stress: 45, anxiety: 40, stability: 65 },
    hopeful: { stress: 32, anxiety: 30, stability: 82 },
    confused: { stress: 58, anxiety: 55, stability: 50 },
    frustrated: { stress: 68, anxiety: 60, stability: 44 },
    guilty: { stress: 57, anxiety: 54, stability: 47 },
    shameful: { stress: 62, anxiety: 58, stability: 43 },
    proud: { stress: 30, anxiety: 28, stability: 84 }
  };

  return profile[emotion] || profile.neutral;
};

function App() {
  const [messages, setMessages] = useState<Message[]>([
    createWelcomeMessage()
  ]);
  const [categories, setCategories] = useState<CategoryInfo[]>([]);
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [currentUserId, setCurrentUserId] = useState('user1');
  const [trendData, setTrendData] = useState<HistoryDataPoint[]>([]);
  const [latestReport, setLatestReport] = useState<{
    emotion: QuestionResponse['emotion'];
    risk: QuestionResponse['risk'];
    emotionStyle: QuestionResponse['emotionStyle'];
    report: string;
  } | null>(null);
  const [isDemoMode, setIsDemoMode] = useState(false);
  const [showDemoPanel, setShowDemoPanel] = useState(true);

  useEffect(() => {
    const fetchCategories = async () => {
      try {
        const cats = await getCategories();
        setCategories(cats);
      } catch (error) {
        console.error('Failed to fetch categories:', error);
      }
    };
    fetchCategories();
  }, []);

  useEffect(() => {
    const fetchProgress = async () => {
      try {
        const progress = await getUserProgress(currentUserId);
        const data: HistoryDataPoint[] = progress.history.map((h, index) => ({
          date: `第${index + 1}次`,
          // Use deterministic synthetic baseline instead of random values.
          stressLevel: 45 + (index % 4) * 5,
          anxietyLevel: 38 + (index % 5) * 4,
          moodStability: 62 - (index % 3) * 3
        }));
        setTrendData(data);
      } catch (error) {
        console.error('Failed to fetch progress:', error);
      }
    };
    fetchProgress();
  }, [currentUserId]);

  const handleSend = async (question: string, description: string) => {
    setMessages((prev) => [
      ...prev,
      { id: Date.now().toString(), type: 'user', content: question, timestamp: new Date().toLocaleString('zh-CN') }
    ]);

    setIsLoading(true);

    try {
      const response: QuestionResponse = await askQuestion(question, description, currentUserId);

      setLatestReport({
        emotion: response.emotion,
        risk: response.risk,
        emotionStyle: response.emotionStyle,
        report: response.report
      });

      setMessages((prev) => [
        ...prev,
        {
          id: (Date.now() + 1).toString(),
          type: 'bot',
          content: response.answer,
          knowledgeSources: response.knowledgeSources,
          similarQuestions: response.similarQuestions,
          emotion: response.emotion,
          risk: response.risk,
          emotionStyle: response.emotionStyle,
          report: response.report,
          timestamp: new Date().toLocaleString('zh-CN')
        }
      ]);

      const metrics = emotionToMetrics(response.emotion.emotion);
      setTrendData((prev) => [
        ...prev,
        {
          date: `第${prev.length + 1}次`,
          stressLevel: metrics.stress,
          anxietyLevel: metrics.anxiety,
          moodStability: metrics.stability
        }
      ]);
    } catch (error) {
      console.error('Error sending question:', error);
      setMessages((prev) => [
        ...prev,
        {
          id: (Date.now() + 1).toString(),
          type: 'bot',
          content: '抱歉，我暂时无法回答您的问题。请稍后再试。',
          timestamp: new Date().toLocaleString('zh-CN')
        }
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSimilarQuestionClick = (question: string) => {
    handleSend(question, '');
  };

  const handleUserChange = (userId: string) => {
    setCurrentUserId(userId);
    setMessages([createWelcomeMessage()]);
    setLatestReport(null);
  };

  const handleNewUser = (userId: string) => {
    setCurrentUserId(userId);
    setMessages([createWelcomeMessage()]);
    setLatestReport(null);
  };

  const handleClearHistory = async () => {
    try {
      await clearUserHistory(currentUserId);
      setMessages([createWelcomeMessage()]);
      setTrendData([]);
      setLatestReport(null);
    } catch (error) {
      console.error('Failed to clear history:', error);
    }
  };

  const handleExportHistory = () => {
    const historyText = messages.map((m) => {
      return `${m.type === 'user' ? '用户' : '助手'} [${m.timestamp}]:\n${m.content}\n`;
    }).join('\n---\n\n');

    const blob = new Blob([historyText], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `对话记录_${new Date().toLocaleDateString('zh-CN').replace(/\//g, '-')}.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleDemoQuestion = (question: string) => {
    handleSend(question, '');
  };

  const toggleDemoMode = () => {
    setIsDemoMode(!isDemoMode);
    if (!isDemoMode) {
      setShowDemoPanel(true);
    }
  };

  return (
    <div className="app-container">
      <header className="header">
        <div className="header-left">
          <h1>🏠 心理港湾</h1>
          <p>温暖的心灵栖息地，陪伴您走过每一段旅程</p>
        </div>
        <div className="header-right">
          <div className="current-user">
            当前用户: {currentUserId === 'user1' ? '小明 👦' : currentUserId === 'user2' ? '小红 👧' : currentUserId === 'user3' ? '小李 👨' : '新用户'}
          </div>
          <button 
            className={`demo-toggle ${isDemoMode ? 'active' : ''}`}
            onClick={toggleDemoMode}
          >
            🎬 {isDemoMode ? '退出演示' : '演示模式'}
          </button>
        </div>
      </header>

      <main className="main-content">
        <aside className="sidebar-panel">
          <UserSelector
            currentUserId={currentUserId}
            onUserChange={handleUserChange}
            onNewUser={handleNewUser}
          />
          <Sidebar
            categories={categories}
            activeCategory={activeCategory}
            onCategorySelect={setActiveCategory}
          />
        </aside>

        <div className="main-panel">
          <div className="top-section">
            <div className="chart-section">
              <TrendChart data={trendData} />
            </div>
            {latestReport && (
              <div className="report-section">
                <ReportPanel
                  emotion={latestReport.emotion}
                  risk={latestReport.risk}
                  emotionStyle={latestReport.emotionStyle}
                  report={latestReport.report}
                />
              </div>
            )}
          </div>
          {isDemoMode && showDemoPanel && (
            <div className="demo-panel">
              <div className="demo-header">
                <h3>🎯 快捷体验</h3>
                <button className="demo-close" onClick={() => setShowDemoPanel(false)}>✕</button>
              </div>
              <div className="demo-questions">
                {DEMO_QUESTIONS.map((question, index) => (
                  <button
                    key={index}
                    className="demo-question-btn"
                    onClick={() => handleDemoQuestion(question)}
                  >
                    💡 {question}
                  </button>
                ))}
              </div>
            </div>
          )}
          <div className="chat-section">
            <ChatContainer
              messages={messages}
              isLoading={isLoading}
              onSend={handleSend}
              onSimilarQuestionClick={handleSimilarQuestionClick}
              onClearHistory={handleClearHistory}
              onExportHistory={handleExportHistory}
            />
          </div>
        </div>
      </main>
    </div>
  );
}

export default App;
